import sys, numpy as np
from rdkit import Chem
def norm(v): return v/np.linalg.norm(v)
z=np.array([0,0,1.0])
pos = {
 'Ot':np.array([ 0.00, 1.45,0.0]), 'A':np.array([-1.15, 0.75,0.0]),
 'Cp':np.array([ 1.15, 0.75,0.0]), 'B':np.array([-0.70,-0.55,0.0]),
 'D' :np.array([ 0.70,-0.55,0.0]), 'F':np.array([-1.15,-1.85,0.0]),
 'G' :np.array([ 1.15,-1.85,0.0]), 'Ob':np.array([ 0.00,-2.55,0.0]),
}
def sub2(X,N1,N2,sgn):
    u1=norm(pos[N1]-pos[X]); u2=norm(pos[N2]-pos[X]); s=-norm(u1+u2)
    return norm(0.82*s + sgn*0.57*z)
def sub3(X,N1,N2,N3,sgn):
    u=norm(pos[N1]-pos[X])+norm(pos[N2]-pos[X])+norm(pos[N3]-pos[X]); s=-norm(u)
    return norm(0.55*s + sgn*0.90*z)
pos['OHA']=pos['A']+1.43*sub2('A','Ot','B',-1); pos['OHG']=pos['G']+1.43*sub2('G','D','Ob',-1)
pos['ipsoF']=pos['F']+1.50*sub2('F','B','Ob',-1); pos['ipsoCp']=pos['Cp']+1.50*sub2('Cp','Ot','D',-1)
pos['HB']=pos['B']+1.09*sub3('B','A','F','D',+1); pos['HD']=pos['D']+1.09*sub3('D','Cp','G','B',+1)
pos['HA']=pos['A']+1.09*sub2('A','Ot','B',+1); pos['HG']=pos['G']+1.09*sub2('G','D','Ob',+1)
pos['HF']=pos['F']+1.09*sub2('F','B','Ob',+1); pos['HCp']=pos['Cp']+1.09*sub2('Cp','Ot','D',+1)
centers = {'A':('A',['Ot','B','OHA','HA']),'Cp':('Cp',['Ot','D','ipsoCp','HCp']),
 'F':('F',['B','Ob','ipsoF','HF']),'G':('G',['D','Ob','OHG','HG']),
 'B':('B',['A','F','D','HB']),'D':('D',['Cp','G','B','HD'])}
def chivol4(get,x,nbs):
    X=get(x); p,q,r,s=(get(nb)-X for nb in nbs)
    return np.linalg.det(np.array([p-s,q-s,r-s]).T)
ideal={c: np.sign(chivol4(lambda k: pos[k], x, nbs)) for c,(x,nbs) in centers.items()}

fname=sys.argv[1]
smi=sys.argv[2]
mol=Chem.AddHs(Chem.MolFromSmiles(smi))
mp={'A':1,'Ot':2,'Cp':3,'ipsoCp':4,'D':13,'B':14,'F':15,'ipsoF':16,'Ob':25,'G':26,'OHG':27,'OHA':0}
for name,heavy in [('HA','A'),('HCp','Cp'),('HF','F'),('HG','G'),('HB','B'),('HD','D')]:
    mp[name]=[a.GetIdx() for a in mol.GetAtomWithIdx(mp[heavy]).GetNeighbors() if a.GetAtomicNum()==1][0]
lines=open(fname).read().splitlines()
n=int(lines[0]); P=[]
for l in lines[2:2+n]:
    p=l.split(); P.append([float(p[1]),float(p[2]),float(p[3])])
P=np.array(P)
assert P.shape[0]==mol.GetNumAtoms()
get=lambda k: P[mp[k]]
allok=True
for c,(x,nbs) in centers.items():
    s=np.sign(chivol4(get,x,nbs)); ok = s==ideal[c]; allok &= ok
    print(f"  {c}: {'OK' if ok else 'MISMATCH'}")
print("CONFIGURATION:", "MATCHES DEPICTION (all-cis, bridgehead H opposite face)" if allok else "WRONG")
